# Print the structure
def find_cpi(obj, path=''):
    if isinstance(obj, dict):
        for key, value in obj.items():
            if 'cpi' in key.lower() or 'price' in key.lower() or 'index' in key.lower():
                print(f'{path}.{key}: {value}')
            find_cpi(value, f'{path}.{key}')
    elif isinstance(obj, list):
        for i, item in enumerate(obj):
            find_cpi(item, f'{path}[{i}]')

find_cpi(data)
